CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,display_name TEXT NOT NULL,birth_date DATE NOT NULL,country TEXT NOT NULL,city TEXT DEFAULT '',languages TEXT DEFAULT '',relationship_goal TEXT DEFAULT 'Serious relationship',bio TEXT DEFAULT '',photo_url TEXT DEFAULT '',role TEXT NOT NULL DEFAULT 'user',is_suspended BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS likes(liker_id BIGINT REFERENCES users(id) ON DELETE CASCADE,liked_id BIGINT REFERENCES users(id) ON DELETE CASCADE,created_at TIMESTAMPTZ DEFAULT NOW(),PRIMARY KEY(liker_id,liked_id));
CREATE TABLE IF NOT EXISTS matches(id BIGSERIAL PRIMARY KEY,user1_id BIGINT REFERENCES users(id) ON DELETE CASCADE,user2_id BIGINT REFERENCES users(id) ON DELETE CASCADE,created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user1_id,user2_id));
CREATE TABLE IF NOT EXISTS messages(id BIGSERIAL PRIMARY KEY,match_id BIGINT REFERENCES matches(id) ON DELETE CASCADE,sender_id BIGINT REFERENCES users(id) ON DELETE CASCADE,body TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS reports(id BIGSERIAL PRIMARY KEY,reporter_id BIGINT REFERENCES users(id) ON DELETE CASCADE,reported_id BIGINT REFERENCES users(id) ON DELETE CASCADE,reason TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS blocks(blocker_id BIGINT REFERENCES users(id) ON DELETE CASCADE,blocked_id BIGINT REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(blocker_id,blocked_id));
